"""Denser random generator with per-partition value patterns."""
import json, random, sys

NUM = ("TIME","SIZE","COUNT")

def base_patterns(rng, fields):
    pats=[]
    for f in fields:
        if f["type"]=="FLAG": pats.append([True,False])
        elif f["type"]=="ID": pats.append(["a","b"])
        else: pats.append([0,1,2])
    return pats

def skew(rng, fields, pats, mode):
    """Return per-field value lists with different skew per mode."""
    out=[]
    for f,p in zip(fields,pats):
        if f["type"]=="FLAG":
            out.append([True] if mode=="train" else ([False] if mode=="probe" else p))
        elif f["type"]=="ID":
            out.append([p[0]] if mode=="train" else ([p[-1]] if mode=="probe" else p))
        else:
            out.append([p[0]] if mode=="train" else ([p[-1]] if mode=="probe" else p))
    return out

def build(seed):
    rng = random.Random(seed)
    K = rng.randint(1,3)
    nf = rng.randint(1,3)
    fields=[]
    for i in range(nf):
        kind = rng.choice(["flag","num","num","id"])
        name="f%d"%i
        if kind=="num":
            fields.append({"name":name,"type":rng.choice(NUM),"min":0,"max":rng.choice([3,10,100])})
        elif kind=="id":
            fields.append({"name":name,"type":"ID","values":["a","b","c"]})
        else:
            fields.append({"name":name,"type":"FLAG"})
    pats = base_patterns(rng, fields)
    modes = {"train":skew(rng,fields,pats,"train"), "probe":skew(rng,fields,pats,"probe"),
             "query":skew(rng,fields,pats,"query")}
    def value(f,p):
        if f["type"]=="FLAG": return rng.choice(p)
        if f["type"]=="ID": return rng.choice(p)
        return max(f["min"], min(f["max"], rng.choice(p)))
    def rows(n, mode):
        out=[]; seen=set()
        for i in range(n):
            vals=[value(f,modes[mode][j]) for j,f in enumerate(fields)]
            t=i*3+rng.randint(0,2)
            while t in seen: t+=1
            seen.add(t)
            out.append({"t":t,"values":vals})
        return out
    def traces(prefix,ntr,nsr,maxrows,mode):
        out=[]
        for i in range(ntr):
            out.append({"id":"%s%d"%(prefix,i),"source":"s%d"%rng.randrange(nsr),
                        "rows":rows(rng.randint(0,maxrows),mode)})
        return out
    atoms=[]
    for _ in range(rng.randint(1,6)):
        f=rng.choice(fields)
        if f["type"]=="FLAG":
            atoms.append({"cmp":rng.choice(["eq","ne"]),"left":{"field":f["name"],"at":rng.randrange(K)},
                          "right":{"const":rng.choice([True,False]),"type":"FLAG"}})
        elif f["type"]=="ID":
            atoms.append({"cmp":rng.choice(["eq","ne"]),"left":{"field":f["name"],"at":rng.randrange(K)},
                          "right":{"const":rng.choice(["a","b"]),"type":"ID"}})
        else:
            atoms.append({"cmp":rng.choice(["eq","ne","lt","le","gt","ge"]),"left":{"field":f["name"],"at":rng.randrange(K)},
                          "right":{"const":rng.randint(0,2),"type":f["type"]}})
    if rng.random()<0.35:
        cands=[f for f in fields if f["type"] in NUM]
        if cands:
            f=rng.choice(cands); lo=rng.randrange(K); hi=rng.randrange(lo,K)
            atoms.append({"quantifier":rng.choice(["any","all"]),"from":lo,"to":hi,
                          "predicate":{"cmp":"ge","left":{"field":f["name"],"at":"$"},"right":{"const":rng.randint(0,2),"type":f["type"]}}})
    if rng.random()<0.35:
        cands=[f for f in fields if f["type"] in NUM]
        if cands:
            f=rng.choice(cands); lo=rng.randrange(K); hi=rng.randrange(lo,K)
            atoms.append({"cmp":rng.choice(["ge","le","gt","lt","eq"]),
                          "left":{"aggregate":rng.choice(["sum","mean","min","max"]),"field":f["name"],"from":lo,"to":hi},
                          "right":{"const":rng.randint(0,4),"type":f["type"]}})
    return {"version":1,"schema":fields,"window":K,"atoms":atoms,
            "policy":{"max_width":rng.randint(1,4),"min_support":rng.randint(1,2),"min_witness":rng.randint(1,2)},
            "train":traces("t",rng.randint(1,3),rng.randint(1,2),rng.randint(2,8),"train"),
            "probes":traces("p",rng.randint(1,2),1,rng.randint(1,4),"probe"),
            "queries":traces("q",rng.randint(1,2),1,rng.randint(1,6),"query")}

if __name__=="__main__":
    print(json.dumps(build(int(sys.argv[1]))))
